examples.reusable_method:
def click_back_button(self, screen_name):
    locator = self.get_back_button_locator(screen_name)
    self.click_element(locator)

examples.error_handling:
try:
    self.click_element(locator)
except ElementNotFoundError as e:
    self.capture_screenshot('element_not_found')
    self.log_error(f'Failed to click element {locator}: {str(e)}')
    raise TestSetupError('Unable to complete test setup')

examples.explicit_wait:
def wait_for_popup_to_appear(self, timeout=10):
    return WebDriverWait(self.driver, timeout).until(
        EC.visibility_of_element_located(self.popup_locator)
    )

